"""Generate the explicit Lua root registry from the public coverage ledger.

This copies only reviewed identifiers and scope metadata, not game source.
"""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render():
    data = json.loads((ROOT / "docs/window-coverage.json").read_text())
    rows = data["surfaces"]
    assert data["count"] == len(rows) == 172
    assert len({r["id"] for r in rows}) == len(rows)
    quote = lambda s: json.dumps(s, ensure_ascii=False)
    lines = [
        "local _, V = ...",
        "-- Generated by tools/window_catalog.py from the public scope ledger.",
        "-- Registration is conditional on a live frame; it is not runtime acceptance.",
        "-- Boundary entries are never traversed by the native interior adapter.",
        "V.WindowCatalog = {",
    ]
    for row in rows:
        fields = [key + " = " + quote(row[key]) for key in ("id", "frame", "host", "category")]
        if row.get("boundary"):
            fields.append("boundary = " + quote(row["boundary"]))
        if row.get("scan_only"):
            fields.append("scanOnly = true")
        if row.get("aliases"):
            fields.append("aliases = {" + ", ".join(map(quote, row["aliases"])) + "}")
        lines.append("    { " + ", ".join(fields) + " },")
    lines.append("}")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "modules/WindowCatalog.lua"
    expected = render()
    if args.check:
        assert path.read_text() == expected, "WindowCatalog.lua is stale; run python3 tools/window_catalog.py"
        print("window_catalog: public ledger and Lua registry match")
    else:
        path.write_text(expected)
        print("Generated modules/WindowCatalog.lua")
